custom_css:
:root {
  --sakura-glow: 0 0 20px hsl(0 75% 55% / 0.3);
  --samurai-shadow: 0 10px 30px hsl(0 0% 0% / 0.8);
}

.shiranami-glow {
  box-shadow: var(--sakura-glow);
}

.samurai-card {
  background: linear-gradient(135deg, hsl(0 0% 0% / 0.6), hsl(0 30% 10% / 0.4));
  backdrop-filter: blur(10px);
  border: 1px solid hsl(0 30% 25% / 0.5);
}

.sakura-text {
  background: linear-gradient(135deg, hsl(0 75% 65%), hsl(0 55% 45%));
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.warrior-badge {
  background: linear-gradient(45deg, hsl(0 75% 35%), hsl(0 65% 45%));
  box-shadow: 0 4px 15px hsl(0 75% 45% / 0.4);
}

@media (max-width: 768px) {
  .shiranami-hero {
    font-size: 2.5rem;
  }

  .sakura-layout {
    grid-template-columns: 1fr;
  }
}
